// n8n Code node: "Read review request"
// Workflow R is started three ways: by Workflow B ({scope:'used', batch_id}), by the crawler / the
// review-now webhook / a manual run (no scope => 'all').
//   used : only the lender+employment-type pairs that appear in this batch's matches (blocks the emails)
//   all  : every fresh lender, so the cache is complete even for an outlier no user has hit yet
const j = ($input.first() && $input.first().json) || {};
const body = j.body && typeof j.body === 'object' ? j.body : {};
const id = String(j.batch_id || body.batch_id || '');
const batch_id = /^[0-9a-f-]{36}$/i.test(id) ? id : '';
const wanted = j.scope || body.scope;
const scope = wanted === 'used' && batch_id ? 'used' : 'all';
return [{ json: { scope, batch_id } }];

// n8n Code node: "Assign provider"
// Spreads lenders over BOTH providers so their separate free-tier quotas add up. Gemini flash-lite
// allows many more requests per minute than Groq allows tokens per minute, so Gemini takes two
// of every three lenders and Groq one. (n8n runs the two branches one after the other, so the
// gain comes from the faster pacing the Gemini quota allows, not from simultaneous calls.)
return $input.all().map((item, i) => ({ json: { ...item.json, provider: i % 3 === 0 ? 'groq' : 'gemini' } }));

// n8n Code node: "Build review prompt"
// One item per LENDER (not per employment type): plan_reviews.sql groups a lender's stale
// segments, so one call returns a note for each of its employment types. The system prompt and the
// lender text are sent once instead of up to three times, which is what the free-tier token limit
// is measured in.
const SYSTEM = "You help explain personal-loan eligibility to customers. Applicants have ALREADY been checked against the lender's numeric rules (monthly income, credit score, age) and the employment types the lender accepts. Your job is only to say how confident the match is and, when relevant, what the customer still needs to check.

You receive: one lender product, the applicant employment types to assess, the lender's qualitative requirements (a summary) and the lender's original source text (ground truth).

IMPORTANT: our customer database contains ONLY employment type, monthly income, credit score and age. It has NO information about work experience, employer or employer category, city, education, profession, an existing bank account or relationship, or nationality.

You NEVER reject applicants. Numeric limits and accepted employment types are already decided; do not re-judge them.

Return ONLY a JSON object with one entry for EACH requested employment type, keyed by the exact type name:
{"reviews":{"Salaried":{"verdict":"conditional","caveat":"..."},"Business":{"verdict":"eligible","caveat":null}}}
- verdict "eligible": the qualitative requirements place no extra conditions on this employment type.
- verdict "conditional": the applicant may qualify, but it depends on facts missing from our database (work experience, employer type, city, profession, existing bank relationship, account activity, nationality, ...). Name the most important ones in the caveat.
- caveat: one plain-English sentence addressed to the customer, at most 140 characters, no jargon; null when the verdict is "eligible". Only state conditions that appear in the lender's text, and say which kind of applicant they apply to; never invent a threshold.";

return $input.all().map(({ json: s }) => ({
  json: {
    ...s,
    system_prompt: SYSTEM,
    user_prompt:
      `Lender product: ${s.product_name}
` +
      `Applicant employment types to assess: ${s.employment_types.join(', ')}

` +
      `Lender's qualitative requirements (summary):
${s.qualitative_criteria_text}

` +
      `Lender's source eligibility text (ground truth):
${s.source_text || '(not available)'}`,
  },
}));

// n8n Code node: "Validate <provider> review"  (stamped per provider by build_workflows.py)
// One LLM response covers ONE lender and all of its requested employment types. Output is one item
// per lender: {reviews:[{employment_type, valid, verdict, caveat}], all_valid, extraction_status}.
// all_valid=false (bad JSON, a missing type, an unknown verdict) sends the lender to the fallback.
const PROVIDER = 'groq'; // 'groq' | 'gemini'
// The reviewer may only grade a segment 'eligible' or 'conditional'. An LLM veto proved unreliable on
// real data (it applied a salaried income floor to self-employed applicants, excluded employment types
// the lender accepts, and flipped between runs), so 'ineligible' is demoted to 'conditional': numeric
// rules and employment types are verified exactly in SQL (Stages 1-2), and the LLM must not silently
// remove a user on its own judgement.
const VERDICTS = ['eligible', 'conditional', 'ineligible'];

function responseText(res) {
  if (!res || res.error) return null;
  if (PROVIDER === 'groq') return (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || null;
  const parts = res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts;
  return parts ? parts.map((p) => p.text || '').join('') : null;
}
function parseJson(t) {
  if (!t) return null;
  t = t.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
  try { return JSON.parse(t); } catch (e) { /* fall through */ }
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) { /* give up */ } }
  return null;
}
const norm = (s) => String(s).toLowerCase().replace(/[^a-z]/g, '');

function reviewOne(entry) {
  if (!entry || typeof entry !== 'object') return { valid: false };
  let verdict = typeof entry.verdict === 'string' ? entry.verdict.trim().toLowerCase() : null;
  if (!VERDICTS.includes(verdict)) return { valid: false };
  const demoted = verdict === 'ineligible';
  if (demoted) verdict = 'conditional';
  let caveat = typeof entry.caveat === 'string' ? entry.caveat.trim() : null;
  if (caveat && /^(null|none|n\/a)$/i.test(caveat)) caveat = null;
  if (caveat && caveat.length > 160) caveat = caveat.slice(0, 157) + '...';
  if (verdict === 'eligible') caveat = null;
  if (demoted && !caveat) caveat = 'The lender has extra requirements we could not check.';
  return { valid: true, verdict, caveat, demoted };
}

return $input.all().map((item, i) => {
  const original = $('Build review prompt').itemMatching(i).json;
  const types = original.employment_types;
  const out = (reviews, status, extra) => ({
    json: { ...original, reviews, all_valid: reviews.every((r) => r.valid), extraction_status: status, ...extra },
  });
  const failAll = (why) => out(types.map((t) => ({ employment_type: t, valid: false })), `invalid_${PROVIDER}`, { llm_error: why });

  if (item.json && item.json.error) return failAll(`request failed: ${JSON.stringify(item.json.error).slice(0, 160)}`);
  const parsed = parseJson(responseText(item.json));
  const block = parsed && typeof parsed.reviews === 'object' && parsed.reviews ? parsed.reviews : null;
  if (!block) return failAll('response was not the expected JSON');

  const byKey = {};
  Object.keys(block).forEach((k) => { byKey[norm(k)] = block[k]; });
  const reviews = types.map((t) => ({ employment_type: t, ...reviewOne(byKey[norm(t)]) }));
  const ok = reviews.every((r) => r.valid);
  return out(reviews, ok ? `llm_${PROVIDER}` : `invalid_${PROVIDER}`, {});
});

