// n8n Code node: "Collect rows to save"  (runs once per batch of lenders)
// Flattens the per-lender results into one JSON array for a single upsert query. Only valid
// segments are saved; a segment that no provider could review is left out and retried next run.
const rows = new Map();
const items = $input.all().map((i) => i.json);
for (const it of items) {
  const provider = String(it.extraction_status || '').replace(/^(llm|invalid)_/, '');
  for (const r of it.reviews || []) {
    if (!r.valid) continue;
    rows.set(`${it.product_id}|${r.employment_type}`, {
      product_id: it.product_id, employment_type: r.employment_type, criteria_hash: it.criteria_hash,
      verdict: r.verdict, caveat: r.caveat, provider: `llm_${provider}`,
    });
  }
}
return [{ json: { rows_json: JSON.stringify([...rows.values()]), lenders: items.length, rows: rows.size } }];

// n8n Code node: "Total saved"  (runs once, when the loop has finished every batch)
// $input holds one {saved} row per batch.
return [{ json: { reviews_saved: $input.all().reduce((n, i) => n + Number(i.json.saved || 0), 0) } }];

// n8n Code node: "Review summary"
const planned = $('Plan reviews (cache check)').all().filter((i) => i.json.product_id !== undefined);
const cov = $input.first().json;
const req = $('Read review request').first().json;
return [{
  json: {
    scope: req.scope,
    lenders_reviewed: planned.length,
    notes_saved: $('Total saved').first().json.reviews_saved,
    segments_in_scope: Number(cov.segments_in_scope),
    segments_with_current_note: Number(cov.with_current_note),
    segments_still_missing: Number(cov.missing),   // > 0 => a provider failed; retried on the next run
    finished_at: new Date().toISOString(),
  },
}];
